widget.solution:
from fractions import Fraction
from math import gcd

def first_rationals(k):
    """The first k rationals of [0, 1]: 0, 1, then by denominator, then numerator, in lowest terms."""
    out = [Fraction(0), Fraction(1)]
    d = 2
    while len(out) < k:
        for n in range(1, d):
            if gcd(n, d) == 1:
                out.append(Fraction(n, d))
        d += 1
    return out[:k]

def cover_length(eps, k):
    """Total length of the first k covering intervals, interval j of length eps / 2**j (j = 1, 2, ...)."""
    return sum(Fraction(eps) / 2 ** j for j in range(1, k + 1))

def cantor_left(n):
    """Length left after n stages of the Cantor set."""
    return Fraction(2, 3) ** n
